import { test, expect } from '@playwright/test';

test.describe('Record Date Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records'); // Navigate to the records page
  });

  test('should display created date for a record', async ({ page }) => {
    const record = await page.getByText('Sample Record'); // Replace with actual record name
    await expect(record).toBeVisible();

    const createdDate = await record.getByRole('cell', { name: /created date/i });
    await expect(createdDate).toBeVisible();
    await expect(createdDate).toHaveText(/^\d{4}-\d{2}-\d{2}/); // Check for date format
  });

  test('should display last modified date for a record', async ({ page }) => {
    const record = await page.getByText('Sample Record'); // Replace with actual record name
    await expect(record).toBeVisible();

    const modifiedDate = await record.getByRole('cell', { name: /last modified date/i });
    await expect(modifiedDate).toBeVisible();
    await expect(modifiedDate).toHaveText(/^\d{4}-\d{2}-\d{2}/); // Check for date format
  });
});
